// Игра-фикстура для теста слоёв, параллакса и затемнения.
//
// Даёт тесту три слоя на разных порядках и потомков внутри них, чтобы
// проверить распространение порядка/видимости, параллакс и полноэкранные
// оттенки. Ничего не двигается само: камеру и узлы крутит тест.

$.ready(() => {
    $.world.gravity(0, 0).color('#101820');

    // Дальний план: слой с параллаксом 0.5 — его дети наследуют коэффициент.
    const bg = $.layers.create({ name: 'bg', order: -10, parallax: 0.5 });
    for (let i = 0; i < 8; i++) {
        $('<rect>', { id: i === 0 ? 'star0' : 'star' + i, class: 'star' })
            .at(60 + i * 90, 80 + (i % 3) * 40)
            .size(12, 12)
            .color('#2b4a7a')
            .appendTo(bg);
    }

    // Игровой слой: обычный мир без слоя.
    $('<player>', { id: 'hero' }).at(200, 300).size(28, 40).appendTo($.world);
    $('<rect>', { id: 'block', class: 'block' })
        .at(400, 300).size(40, 40).color('#4fd166').appendTo($.world);

    // Интерфейсный слой поверх мира.
    const hud = $.layers.create({ name: 'hud', order: 20 });
    $('<rect>', { id: 'hud_strip' }).at(400, 30).size(800, 60)
        .color('#000000aa').appendTo(hud);
});
